import { createQuery, queryOptions as createQueryOptions, } from '@tanstack/svelte-query';
import { usePolling } from '../use-polling.svelte';
import { createQueryLogger } from '../../logger';
import { useViamClient } from './use-app-client.svelte';
export const createAppQuery = (method, ...additional) => {
    const viamClient = useViamClient();
    const appClient = $derived(viamClient.current?.appClient);
    let [args, options] = additional;
    if (options === undefined && args !== undefined) {
        options = args;
        args = undefined;
    }
    const _options = $derived(typeof options === 'function' ? options() : options);
    const _args = $derived(typeof args === 'function' ? args() : args);
    const methodName = $derived(String(method));
    const enabled = $derived(appClient !== undefined && _options?.enabled !== false);
    const queryOptions = $derived(createQueryOptions({
        queryKey: [
            'viam-svelte-app-sdk',
            'appClient',
            methodName,
            ...(_args ? [_args] : []),
        ],
        enabled,
        queryFn: async () => {
            if (!appClient) {
                throw new Error('appClient is undefined');
            }
            const clientFunc = appClient[method];
            if (typeof clientFunc !== 'function') {
                throw new TypeError(`${String(method)} is not a method on the resource client.`);
            }
            const logger = createQueryLogger('appClient', methodName);
            logger.request(_args);
            try {
                const response = (await clientFunc.apply(appClient, _args));
                logger.response(response);
                return response;
            }
            catch (error) {
                logger.error(error);
                throw error;
            }
        },
        ..._options,
        refetchInterval: false,
    }));
    usePolling(() => queryOptions.queryKey, () => enabled && (_options?.refetchInterval ?? false));
    return createQuery(() => queryOptions);
};
